# Read original books.js lines or import it
with open("src/data/books.js", "r", encoding="utf-8") as f:
    content = f.read()

import re

# parse initialBooks array from JS content
# We can load the json directly by extracting array string
match = re.search(r"export const initialBooks = (\[.*\]);", content, re.DOTALL)
if not match:
    print("Could not find initialBooks in JS file!")
    exit(1)

books_json = match.group(1)
books = json.loads(books_json)

for book in books:
    b_id = book["id"]
    if b_id in descriptions:
        book["description"] = descriptions[b_id]
    else:
        print(f"Missing description for {b_id}")

new_books_json = json.dumps(books, ensure_ascii=False, indent=2)

new_content = f"// Automaticky generovaná databáze knih pro školní knihovnu\n\nexport const initialBooks = {new_books_json};\n"

with open("src/data/books.js", "w", encoding="utf-8") as f:
    f.write(new_content)

print(f"Successfully updated descriptions for {len(books)} books!")
